import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("opening balances", () => {
  test("opening balances", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-25");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-10"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-11", "to": "2026-03-20"})).toBe(true);
    expect(await ui.addAlias(pg_uma, p_ben, "Benny")).toBe(true);
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00", "date": "2026-03-05"}));
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    expect(await ui.importOpenings(pg_uma, "Ada,P2,5.00\nbenny,P1,2.50")).toBe(2);
    expect(await ui.importOpenings(pg_uma, "Ada,P2,1.005")).toBeNull();
    expect(await ui.importOpenings(pg_uma, "Ada,P3,1.00")).toBeNull();
    expect(await ui.importOpenings(pg_uma, "Zed,P1,1.00")).toBeNull();
    expect(await ui.importOpenings(pg_uma, "Ada,P2,-1.00")).toBeNull();
